sysauto_script.script:
(function() {
  var TABLE = "x_vuram_financia_0_fcc_kyc_cases";
  var EVENT_NAME = "x_vuram_financia_0.kyc.awaiting.customer"; // full event name
  var REMINDER_LIMIT = 4;
  var REMINDER_GAP_DAYS = 5;

  var nowGdt = new GlideDateTime();

  var gr = new GlideRecord(TABLE);
  gr.addQuery("state", "250");  // On Hold only
  gr.addQuery("chaser_count", "<", REMINDER_LIMIT);
  gr.addNotNullQuery("next_chaser_due");
  gr.addQuery("next_chaser_due", "<=", nowGdt);
  gr.query();

  gs.info("[KYC Chaser Job] Now = " + nowGdt.getDisplayValue());

  // Check if we have any records at all
  if (!gr.hasNext()) {
    gs.info("[KYC Chaser Job] No eligible cases found.");
    return;
  }

  var processedCount = 0;

  while (gr.next()) {
    processedCount++;
    gs.info("[KYC Chaser Job] Processing case " + gr.getDisplayValue("number"));

    // Fire event → Notification should be wired to this
    gs.eventQueue(EVENT_NAME, gr, gr.getValue("u_customer_email"), gr.getDisplayValue("number"));
    gs.info("[KYC Chaser Job] Event fired: " + EVENT_NAME + " for case " + gr.getDisplayValue("number"));

    // Increment counter + update fields
    var newCount = parseInt(gr.getValue("chaser_count"), 10) || 0;
    newCount++;
    gr.setValue("chaser_count", newCount);

    var stamp = new GlideDateTime(); // now
    gr.setValue("last_chaser_date", stamp);

    if (newCount < REMINDER_LIMIT) {
      var next = new GlideDateTime(stamp);
      next.addDaysLocalTime(REMINDER_GAP_DAYS);
      gr.setValue("next_chaser_due", next);
      gs.info("[KYC Chaser Job] Next chaser due: " + next.getDisplayValue());
    } else {
      gr.setValue("next_chaser_due", ""); // stop after 4th
      gs.info("[KYC Chaser Job] Reminder limit reached. Stopping chasers.");
    }

    gr.work_notes = "Automated chaser #" + newCount +
                    " sent for KYC case " + gr.getDisplayValue("number") + ".";
    gr.setWorkflow(false);
    gr.update();

    gs.info("[KYC Chaser Job] Updated case " + gr.getDisplayValue("number") +
            " → chaser_count=" + newCount);
  }

  gs.info("[KYC Chaser Job] Total cases processed: " + processedCount);
})();
